// scratchAI: offline support. The editor's files are listed in precache-manifest.json
// (generated by webpack.config.js) and cached on install. Requests to other origins,
// such as AI APIs, are never intercepted.

const CACHE_PREFIX = 'scratchai-';
const base = new URL('./', self.location).href;

const manifestUrl = `${base}precache-manifest.json`;

self.addEventListener('install', event => {
    event.waitUntil((async () => {
        const response = await fetch(manifestUrl, {cache: 'no-store'});
        const manifest = await response.json();
        const cache = await caches.open(`${CACHE_PREFIX}${manifest.version}`);
        // Cache in small groups so one failing file does not abort everything.
        const urls = [base, ...manifest.files.map(file => `${base}${file}`)];
        for (let i = 0; i < urls.length; i += 20) {
            await Promise.all(urls.slice(i, i + 20).map(url => cache.add(url).catch(() => null)));
        }
        await self.skipWaiting();
    })());
});

self.addEventListener('activate', event => {
    event.waitUntil((async () => {
        const response = await fetch(manifestUrl, {cache: 'no-store'}).catch(() => null);
        const manifest = response && response.ok ? await response.json() : null;
        const keep = manifest ? `${CACHE_PREFIX}${manifest.version}` : null;
        const keys = await caches.keys();
        await Promise.all(keys
            .filter(key => !keep || key !== keep)
            .filter(key => keep || !key.startsWith(CACHE_PREFIX))
            .map(key => caches.delete(key)));
        await self.clients.claim();
    })());
});

self.addEventListener('fetch', event => {
    const request = event.request;
    if (request.method !== 'GET' || !request.url.startsWith(base)) return;
    if (request.mode === 'navigate') {
        // Pages: prefer the network so updates show up, fall back to the cache offline.
        event.respondWith(fetch(request).catch(async () => {
            const cached = await caches.match(request, {ignoreSearch: true});
            return cached || caches.match(`${base}editor.html`);
        }));
        return;
    }
    // Scripts and assets have content hashes in their names: cache first.
    event.respondWith((async () => {
        const cached = await caches.match(request, {ignoreSearch: true});
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) {
            const keys = await caches.keys();
            const current = keys.filter(key => key.startsWith(CACHE_PREFIX)).pop();
            if (current) (await caches.open(current)).put(request, response.clone());
        }
        return response;
    })());
});
